import { Link } from 'react-router-dom';
import { ArrowRightIcon, CalendarIcon, ClockIcon } from './icons.jsx';
import Picture from './Picture.jsx';
import { cardImage } from '../lib/cardImage.js';

/** "August 4, 2026" from YYYY-MM-DD (a time and offset after the date are ignored). */
export function formatPostDate(iso) {
  const date = new Date(`${String(iso).slice(0, 10)}T00:00:00`);
  return date.toLocaleDateString('en-CA', { year: 'numeric', month: 'long', day: 'numeric' });
}

/**
 * Post modules (src/data/posts/<slug>.js, generated by build-blog-data.mjs):
 * everything a post page shows, one lazy chunk each. The map is created once,
 * at module level; the post page loads its post through loadPost and cards
 * prefetch it on hover, focus or touch so opening the post is instant.
 */
const POST_MODULES = import.meta.glob('../data/posts/*.js');
const postRequests = new Map();

/** True when `slug` is a published post (only published posts get a module). */
export function hasPost(slug) {
  return Boolean(POST_MODULES[`../data/posts/${slug}.js`]);
}

/** A published post with its body and related cards, or null if there is none. */
export function loadPost(slug) {
  if (!postRequests.has(slug)) {
    const load = POST_MODULES[`../data/posts/${slug}.js`];
    const request = (load ? load().then((mod) => mod.default) : Promise.resolve(null)).catch((error) => {
      // A failed request (e.g. offline) is retried the next time it is needed.
      postRequests.delete(slug);
      throw error;
    });
    postRequests.set(slug, request);
  }
  return postRequests.get(slug);
}

export function prefetchPost(slug) {
  loadPost(slug).catch(() => {});
}

/**
 * Rendered image widths (pages.css): one column up to 680px, two up to 1024px,
 * then three in the 1300px container (~400px); the featured card's image is
 * full width up to 1024px, then 52% of the container.
 */
const CARD_SIZES = '(max-width: 680px) 100vw, (max-width: 1024px) 50vw, 400px';
const FEATURED_SIZES = '(max-width: 1024px) 100vw, 652px';

export default function BlogCard({ post, featured = false }) {
  const prefetch = () => prefetchPost(post.slug);
  // A post without a hero photo shows its title card (scripts/build-images.mjs).
  // Until that exists there is no image at all: the media box keeps its 16:9
  // space and background (pages.css), so the grid stays even. Self-hosted
  // images arrive as a compact record (`image`, with `titleCard` set when it
  // is the title card); cardImage rebuilds src and srcsets.
  const image = cardImage(post);
  const imageSrc = image.src;
  const isTitleCard = post.image ? Boolean(post.titleCard) : Boolean(!post.hero && post.heroSrc);

  return (
    <article
      className={`blog-card${featured ? ' is-featured' : ''}`}
      onMouseEnter={prefetch}
      onFocus={prefetch}
      onTouchStart={prefetch}
    >
      <Link
        className={`blog-card-media${isTitleCard ? ' is-title-card' : ''}`}
        to={`/blog/${post.slug}`}
        tabIndex={-1}
        aria-hidden="true"
      >
        {imageSrc && (
          <Picture
            avifSrcSet={image.avifSrcSet}
            srcSet={image.srcSet}
            sizes={featured ? FEATURED_SIZES : CARD_SIZES}
            src={imageSrc}
            alt=""
            width="800"
            height="450"
            loading="lazy"
            decoding="async"
          />
        )}
      </Link>
      <div className="blog-card-body">
        <span className="section-tag">{post.category}</span>
        <h3><Link to={`/blog/${post.slug}`}>{post.title}</Link></h3>
        <p>{post.excerpt}</p>
        <div className="blog-card-foot">
          <span className="blog-meta-item"><CalendarIcon size={14} /> {formatPostDate(post.date)}</span>
          <span className="blog-meta-item"><ClockIcon size={14} /> {post.readMinutes} min read</span>
        </div>
        <Link className="blog-card-link" to={`/blog/${post.slug}`}>
          READ ARTICLE <ArrowRightIcon size={13} />
        </Link>
      </div>
    </article>
  );
}
